from io_shop.accounts import Account
from io_shop.spend_summary import average_spend_per_item_this_month


class Purchase:
    def __init__(self, in_current_month):
        self.in_current_month = in_current_month


class CountingPurchases:
    """A purchase collection that records how many times it was iterated."""

    def __init__(self, purchases):
        self._purchases = list(purchases)
        self.iterations = 0

    def __iter__(self):
        self.iterations += 1
        return iter(self._purchases)


class ExplodingPurchases:
    """A purchase collection that must never be walked."""

    def __iter__(self):
        raise AssertionError(
            "purchase history was scanned on the request path"
        )


def test_the_monthly_average_is_correct_for_a_shopper_who_did_buy():
    account = Account(
        purchases=[Purchase(True), Purchase(True), Purchase(False)],
        total_cents=9000,
        total_this_month_cents=1000,
    )

    assert average_spend_per_item_this_month(account) == 500


def test_a_shopper_with_no_purchases_this_month_averages_zero():
    account = Account(
        purchases=[Purchase(False)],
        total_cents=9000,
        total_this_month_cents=0,
    )

    assert average_spend_per_item_this_month(account) == 0


def test_an_account_with_no_purchases_at_all_averages_zero():
    account = Account(
        purchases=[],
        total_cents=0,
        total_this_month_cents=0,
    )

    assert average_spend_per_item_this_month(account) == 0


def test_the_account_totals_are_stored():
    account = Account(
        purchases=[],
        total_cents=4200,
        total_this_month_cents=700,
    )

    assert account.total_cents == 4200
    assert account.total_this_month_cents == 700


def test_the_purchase_history_is_walked_at_most_once():
    purchases = CountingPurchases(
        [Purchase(True), Purchase(True), Purchase(False)]
    )
    account = Account(
        purchases=purchases,
        total_cents=9000,
        total_this_month_cents=1000,
    )

    for _ in range(5):
        assert average_spend_per_item_this_month(account) == 500

    assert purchases.iterations == 1


def test_a_precomputed_count_means_the_history_is_never_walked():
    account = Account(
        purchases=ExplodingPurchases(),
        total_cents=9000,
        total_this_month_cents=1200,
        purchases_this_month_count=4,
    )

    assert average_spend_per_item_this_month(account) == 300


def test_a_precomputed_count_of_zero_is_honoured():
    account = Account(
        purchases=ExplodingPurchases(),
        total_cents=9000,
        total_this_month_cents=0,
        purchases_this_month_count=0,
    )

    assert average_spend_per_item_this_month(account) == 0
